{
  "run_id": "20260521-113332",
  "collected_at": "2026-05-21T11:40:30Z",
  "selected_event": {
    "title": "SEC opens public input on prediction market ETFs as Polymarket expands event contracts",
    "date": "2026-05-20/2026-05-21",
    "why_this_is_the_biggest_event": "It is the most consequential cross-feed crypto story in the sampled RSS set: it appears in multiple feeds, involves both the SEC and CFTC, touches regulated prediction markets and ETFs, and has market-structure implications beyond a single token or company announcement."
  },
  "summary": "On May 20-21, 2026, the SEC said it is seeking public feedback on prediction market ETFs and other novel ETFs, while Polymarket filed to list U.S. parlays/combinatorial outcome contracts no earlier than May 21. Together, the developments signal growing institutionalization of prediction markets and renewed scrutiny over how event contracts should be regulated.",
  "cross_references": [
    {
      "source_name": "CoinDesk RSS",
      "source_url": "https://www.coindesk.com/arc/outboundfeeds/rss",
      "matched_items": [
        {
          "headline": "Polymarket moves to list parlays while SEC seeks public input on prediction market ETFs",
          "url": "https://www.coindesk.com/policy/2026/05/20/polymarket-moves-to-list-parlays-while-sec-seeks-public-input-on-prediction-market-etfs"
        }
      ]
    },
    {
      "source_name": "Cointelegraph RSS",
      "source_url": "https://cointelegraph.com/rss",
      "matched_items": [
        {
          "headline": "SEC Seeks Feedback on Prediction Markets ETFs",
          "url": "https://cointelegraph.com/news/sec-seeks-public-comment-as-it-weighs-prediction-market-etfs"
        }
      ]
    },
    {
      "source_name": "SEC statement",
      "source_url": "https://www.sec.gov/newsroom/speeches-statements/atkins-statement-novel-exchange-traded-funds-052026",
      "matched_items": [
        {
          "headline": "Statement on Novel Exchange-Traded Funds (ETFs)",
          "url": "https://www.sec.gov/newsroom/speeches-statements/atkins-statement-novel-exchange-traded-funds-052026"
        }
      ]
    }
  ],
  "deep_facts": [
    {
      "fact": "SEC Chair Paul Atkins said ETFs remain a major driver of innovation in securities markets and that ETF assets have tripled since 2019.",
      "source": "SEC statement"
    },
    {
      "fact": "Atkins said novel products raise novel questions and instructed SEC staff to seek public input on how the Commission should respond to recent market changes, including event contract ETFs.",
      "source": "SEC statement"
    },
    {
      "fact": "Polymarket filed a self-certification to list 'combinatorial outcome contracts' (parlays) in U.S. sports event contracts, stating the exchange could list them no earlier than May 21, 2026.",
      "source": "CoinDesk"
    },
    {
      "fact": "Under Polymarket's filing, every leg in the parlay must resolve successfully for the contract to pay $1.00; if any single leg fails, the contract resolves to $0.00.",
      "source": "CoinDesk"
    },
    {
      "fact": "Cointelegraph reported that Bitwise filed in February for PredictionShares ETFs tracking U.S. election results, and Roundhill Investments and GraniteShares also filed for prediction market ETFs.",
      "source": "Cointelegraph"
    },
    {
      "fact": "Cointelegraph said prediction markets now consistently exceed $15 billion in monthly trading volume across sports, elections, financial results, and cultural events.",
      "source": "Cointelegraph"
    },
    {
      "fact": "The policy backdrop is a jurisdictional tension: the CFTC oversees event contracts at the federal level, while state regulators and gambling firms argue sports prediction markets infringe on states' rights to regulate and tax gambling products.",
      "source": "CoinDesk"
    },
    {
      "fact": "The CoinDesk article notes that lawmakers are reviewing prediction markets and the issue is likely to remain in litigation and regulatory focus.",
      "source": "CoinDesk"
    }
  ],
  "event_details": {
    "regulatory_bodies": ["SEC", "CFTC"],
    "market_segment": ["prediction markets", "event contracts", "ETFs"],
    "key_entities": ["Polymarket", "Bitwise", "Roundhill Investments", "GraniteShares", "Paul Atkins"],
    "key_dates": [
      "2026-05-20",
      "2026-05-21"
    ],
    "key_numbers": [
      {
        "label": "ETF assets since 2019",
        "value": "tripled"
      },
      {
        "label": "Prediction markets monthly volume",
        "value": "$15B+"
      },
      {
        "label": "Polymarket listing date floor",
        "value": "no earlier than 2026-05-21"
      }
    ]
  },
  "assessment": {
    "impact": "High",
    "confidence": "High",
    "notes": "This was selected because it was directly corroborated across multiple RSS sources and official-regulator content, and because it is broader in market structure impact than the other sampled headlines."
  }
}

